"""Finalize an unpublished RC ZIP after the exact-image Console8 check."""
from pathlib import Path
import argparse,hashlib,json,shutil,zipfile
parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('prepared',type=Path);parser.add_argument('hardware',type=Path);parser.add_argument('output',type=Path);args=parser.parse_args()
prior=args.prepared;hw=args.hardware;out=args.output;analysis=json.loads((hw/'analysis.json').read_text());meta=json.loads((prior/'package.json').read_text());version='3.1.0_uart0_rc_1'
assert analysis['passed'] and analysis['physical'] and analysis['source_commit']==meta['source_commit'] and analysis['MOS_sha256']==meta['MOS_sha256']
h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();original=prior/version
for line in (original/'SHA256SUMS').read_text().splitlines():
 sha,name=line.split('  ',1);assert h(original/name)==sha,name
out.mkdir(parents=True,exist_ok=False);package=out/version;shutil.copytree(original,package)
evidence=package/'evidence/console8-stock-vdp';evidence.mkdir();shutil.copyfile(hw/'analysis.json',evidence/'analysis.json')
for row in analysis['reports']:shutil.copyfile(hw/'appliance'/row['file'],evidence/row['file'])
for name in ('runs.log','next.txt'):shutil.copyfile(hw/'appliance'/name,evidence/name)
(package/'evidence/qualification-status.json').write_text(json.dumps(dict(hardware_passed=True,hardware_reports=[r['file'] for r in analysis['reports']],stock_VDP_basis=analysis['VDP'],emulator_run=False,emulator_waived=True,source_commit=analysis['source_commit'],MOS_sha256=analysis['MOS_sha256']),indent=2)+'\n')
info=json.loads((package/'build-info.json').read_text())
readme="# Eirene MOS 3.1.0 UART0 RC1\n\nThis release candidate lets an aware application calculate while MOS sends its\nbuffer to the VDP in the background. It uses UART interrupts and 16-byte OTIRX\nrefills. Ordinary startup and synchronous RST18 behavior stay unchanged; legacy\napplications do not silently switch transport.\n\nThis is a prerelease in bgates747's fork, based on Tom Morton's Eirene\n3.1.0_beta_1 and his supplied small asynchronous sender. It is not an upstream\nEirene release. The candidate remains on codex/uart0-async; main is unchanged.\n\n## Qualification\n\nThe exact included MOS passed two consecutive Console8 regression runs,\nR0052 and R0053, with stock Bistromathics VDP 2.16.0 under the agreed test\nprotocol. Both reports match MOS CRC32 3F792F8D and verify all 16,384 payload\nbytes, ordinary output before/after opt-in, callback and NULL callback,\nboundary lengths, second-write BUSY, concurrent RX and source reuse. The Author\nreported the complete test procedure passed, including cold boot and the C\nexample. VDP identity and those visual checks are operator evidence, not an\nindependent firmware fingerprint. The exact-image emulator check was waived.\nRaw reports, journal and the verification summary are in evidence/console8-stock-vdp/.\nThis focused test does not retest the separate VDP receive-recovery race.\n\nEarlier controlled Console8 measurements of the same sender before RC branding\nfound 64.06% more foreground calculation during paced sending than stock MOS.\nDuring flat-out sending it retained 85.5% of its no-traffic calculation rate at\nessentially stock throughput. Those benchmarks used the separately receiver-fixed\nVDP; they are not new stock-VDP performance measurements. These are useful-work\nrates, not exclusive CPU-utilization percentages or demonstrated bulk-speed gains.\n\n## Install and try\n\nCopy this directory to /test/mos-uart0 on your SD card. Keep mos-stock.bin\navailable for normal restoration. From that directory use the installed MOSlet:\n\n```\nflash mos mos-rc1.bin\n```\n\nKeep the updater's normal checks and reboot as prompted. Confirm the banner:\n`Agon Eirene UART0 MOS Version 3.1.0 RC 1`. Stock VDP 2.16.0 is sufficient for\nthe final qualification fixture; no VDP protocol modification is required by\nthe sender and no VDP firmware is included in this MOS ZIP.\n\nType `test` and wait for RC1 PASS and the normal prompt. Repeat `test`, then\nrun `example` and require RC1 EXAMPLE PASS. No switches, LOAD or RUN commands.\nAllow two minutes per test; a stall is a failure and its last progress line is\nuseful. Each test clears the screen and checks every 8192-byte payload. Reports\nuse sequential Rnnnn.log files, next.txt and a START/PASS journal in runs.log.\nKeep failed reports too. The small example prints its work count/checksum and\ndoes not write a separate report. Restore with `flash mos mos-stock.bin` when\nneeded; the included restoration image is official MOS 3.0.2.\n\nIf MOS cannot boot, use https://github.com/AgonPlatform/agon-recovery with the\ncorrect board's documented ZDI wiring. The normal updater/recovery is unchanged.\n\n## Application interface\n\nRead source/docs/uart0-async.md and source/docs/tasks/TM-001/contract.md.\nFork-local RST.LIL08h syscalls are 42h=submit and 43h=try finish. Use foreground\nADL=1, MBASE=0 with interrupts enabled. Keep the one accepted source immutable\nand its callback code alive. Arm completion state before submission. The\nbounded callback runs with DI and only posts state; do substantial work in the\nforeground. A callback releases the source, not the wire or VDP execution.\nFinish before ordinary output, returning or releasing code/data. There is no\nqueue, copied RST18 mode or implicit cleanup for application crashes.\n\nexample/ contains a thin C/AgonDev register bridge, not a reentrant/ISR-safe\nlibrary. The example and fixture check this RC's ROM identity before using its\nfork-local syscalls. No upstream ABI allocation is claimed.\n\n## Contents, source and build\n\n- mos-rc1.bin and mos-rc1.map: exact candidate and linker map.\n- source/: complete frozen matching MOS checkout with original notices.\n- fixture/ and example/: complete generated application sources and Makefiles.\n- test.bin, checks.bin and example.bin: ready applications and comparator.\n- build-info.json: commit, tool/library hashes and generated app identities.\n- evidence/: exact-image regression and pre-branding performance records.\n- licenses/: retained upstream/third-party notices.\n- SHA256SUMS: checksums of every file except the manifest itself.\n\nSource commit: @COMMIT@\nUpstream base: 86b694260e3be3b391284ce4aa8ecc758f7f34e9 (3.1.0_beta_1).\nRelease tag: 3.1.0_uart0_rc_1.\nMOS: @BYTES@ bytes; CRC32 @CRC@; SHA256 @SHA@.\n\nsource/ is the frozen build snapshot. Its earlier task notes retain their\nhistorical status; the release qualification above and evidence/ contain the\nsubsequent results. No firmware or application source/binary was changed after\nhardware qualification. Two clean MOS builds produced identical bytes. Relative\nto the pre-branding hardware candidate, only version.h and the banner-emitting\nmain.o differ; the sender and other checked MOS objects are identical.\n\nEirene uses AgonDev, not the older official MOS's ZDS II toolchain. With the\nmatching compiler and Agon libraries identified in build-info.json:\n\n```\nmake -C source AGONDEV_TOOLCHAIN=/absolute/path/to/agondev\nmake -C fixture AGONDEV_TOOLCHAIN=/absolute/path/to/agondev\nmake -C example AGONDEV_TOOLCHAIN=/absolute/path/to/agondev\n```\n\nOutput is bin/mos.bin in source/, bin/test.bin in fixture/ and bin/example.bin\nin example/. The generated identity headers match the included MOS bytes.\nDo not use parallel make for a pristine MOS build: the inherited Makefile does\nnot order creation of its output directories for parallel compilation. No HEX\nconversion is required. The inherited compiler diagnostics were unchanged;\nthe example and fixture compiled with warnings treated as errors.\n\nQualification is limited to the documented Console8 and earlier sender-model\nconfigurations. Other boards, EMOS fit/compatibility, indefinite sustained rates\nand real application/audio deadlines remain separate work.\n\nCredits include Tom Morton, Dean Belfield and the upstream Agon developers.\nThe original async_vdu.asm, source hash, audit and attribution remain in source/.\nOriginal MOS, FatFS/ChaN, allocator and library notices are retained in source/\nand licenses/. Our additions retain the project's MIT terms. Stock restoration\nMOS SHA256: d564243283972690933a4554296ad6202ca4ef54572279533a942960846bebae.\n"
for key,value in (('@COMMIT@',info['source_commit']),('@BYTES@',str(info['MOS_bytes'])),('@CRC@',info['MOS_crc32']),('@SHA@',info['MOS_sha256'])):readme=readme.replace(key,value)
(package/'README.md').write_text(readme)
for name,pin in (('mos-rc1.bin',info['MOS_sha256']),('test.bin',info['test_sha256']),('example.bin',info['example_sha256']),('checks.bin',info['checks_sha256'])):assert h(package/name)==pin,name
# Protect every frozen MOS and generated-app source file from accidental edits.
for tree in ('source','fixture','example'):
 for f in (original/tree).rglob('*'):
  if f.is_file():assert h(package/f.relative_to(original))==h(f),f
files=[f for f in sorted(package.rglob('*')) if f.is_file() and f!=package/'SHA256SUMS'];(package/'SHA256SUMS').write_text(''.join(h(f)+'  '+str(f.relative_to(package))+'\n' for f in files))
archive=out/(version+'.zip')
with zipfile.ZipFile(archive,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=9) as z:
 for f in sorted(package.rglob('*')):
  if f.is_file():z.write(f,arcname=str(f.relative_to(out)))
with zipfile.ZipFile(archive) as z:
 assert z.testzip() is None
 for line in z.read(version+'/SHA256SUMS').decode().splitlines():
  sha,name=line.split('  ',1);assert hashlib.sha256(z.read(version+'/'+name)).hexdigest()==sha,name
archive.with_suffix('.zip.sha256').write_text(h(archive)+'  '+archive.name+'\n')
result=dict(source_commit=info['source_commit'],MOS_sha256=info['MOS_sha256'],test_sha256=info['test_sha256'],example_sha256=info['example_sha256'],zip_name=archive.name,zip_sha256=h(archive),zip_bytes=archive.stat().st_size,hardware_passed=True,VDP='Stock Bistromathics 2.16.0; operator protocol evidence',reports=[r['file'] for r in analysis['reports']],receiver_bytes=analysis['receiver_bytes'],firmware_and_app_sources_unchanged=True,published=False)
(out/'package.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
